{
  /* Simplified UART transmit in interrupt mode for emulation */
  /* Skip all hardware register writes and use HAL_BE_Out instead */

  /* Check that a Tx process is ongoing */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* Calculate output size based on data format */
    size_t output_size;
    if ((huart->Init.WordLength == UART_WORDLENGTH_9B) && (huart->Init.Parity == UART_PARITY_NONE))
    {
      /* For 9-bit data, output 2 bytes */
      output_size = 2;
      huart->pTxBuffPtr += 2U;
    }
    else
    {
      /* For 8-bit data, output 1 byte */
      output_size = 1;
      huart->pTxBuffPtr += 1U;
    }

    /* Use HAL_BE_Out to write data to stdout */
    HAL_BE_Out(output_size);

    /* Decrement transfer count */
    if (huart->TxXferCount > 0)
    {
      huart->TxXferCount--;
    }

    /* Check if transmission is complete */
    if (huart->TxXferCount == 0U)
    {
      /* Transmission complete - state will be updated by UART_EndTransmit_IT */
      /* Don't update state here to match original flow */
    }

    return HAL_OK;
  }
  else
  {
    return HAL_BUSY;
  }
}

