  /* Check if we're in receive mode */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Simulate data received - read from stdin */
    if (huart->pRxBuffPtr != NULL && huart->RxXferSize > 0)
    {
      /* Read available data */
      int bytes_read = HAL_BE_In(huart->pRxBuffPtr, huart->RxXferSize);
      if (bytes_read > 0)
      {
        huart->RxXferCount = huart->RxXferSize - bytes_read;

        /* Call receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
        if (huart->RxCpltCallback != NULL)
        {
          huart->RxCpltCallback(huart);
